1	package agentusage
2	
3	import "sort"
4	
5	// Categories is a session's tokens by kind, the cache writes split by cache
6	// lifetime.
7	type Categories struct {
8		Input, Output, CacheWrite5m, CacheWrite1h, CacheRead int64
9	}
10	
11	// Total is the sum of the five kinds, saturating at math.MaxInt64.
12	func (c Categories) Total() int64 {
13		return satAdd(satAdd(satAdd(c.Input, c.Output), satAdd(c.CacheWrite5m, c.CacheWrite1h)), c.CacheRead)
14	}
15	
16	// Categories sums every agent's tokens by kind. Input, Output, CacheRead and
17	// the total cache write come from Agent.Tokens (so the total equals
18	// Usage.Total().Total()); the 1 h part is the sum of ByModel's CacheWrite1h,
19	// clamped to the total write; the 5 min part is the rest. An agent without
20	// ByModel counts all its writes as 5 min.
21	func (u Usage) Categories() Categories {
22		t := u.Total()
23		var w1h int64
24		for _, a := range u.Agents {
25			for _, m := range a.ByModel {
26				w1h = satAdd(w1h, max(m.CacheWrite1h, 0))
27			}
28		}
29		w1h = min(w1h, t.CacheWrite)
30		return Categories{
31			Input:        t.Input,
32			Output:       t.Output,
33			CacheRead:    t.CacheRead,
34			CacheWrite1h: w1h,
35			CacheWrite5m: t.CacheWrite - w1h,
36		}
37	}
38	
39	// ModelTotals merges every agent's ByModel by exact model name. An agent with
40	// tokens and no ByModel adds its tokens to the "" bucket (as pricing.Agent
41	// does). Order: tokens descending, then name; the "" bucket last.
42	func (u Usage) ModelTotals() []ModelUsage {
43		byName := map[string]*ModelUsage{}
44		add := func(m ModelUsage) {
45			e := byName[m.Model]
46			if e == nil {
47				e = &ModelUsage{Model: m.Model}
48				byName[m.Model] = e
49			}
50			e.Tokens = e.Tokens.Add(m.Tokens)
51			e.CacheWrite1h = satAdd(e.CacheWrite1h, max(m.CacheWrite1h, 0))
52		}
53		for _, a := range u.Agents {
54			if len(a.ByModel) == 0 {
55				if a.Tokens != (Tokens{}) {
56					add(ModelUsage{Tokens: a.Tokens})
57				}
58				continue
59			}
60			for _, m := range a.ByModel {
61				add(m)
62			}
63		}
64		if len(byName) == 0 {
65			return nil
66		}
67		out := make([]ModelUsage, 0, len(byName))
68		for _, e := range byName {
69			out = append(out, *e)
70		}
71		sort.Slice(out, func(i, j int) bool {
72			a, b := out[i], out[j]
73			if (a.Model == "") != (b.Model == "") {
74				return b.Model == ""
75			}
76			if at, bt := a.Tokens.Total(), b.Tokens.Total(); at != bt {
77				return at > bt
78			}
79			return a.Model < b.Model
80		})
81		return out
82	}
83

