21		title string // "By category", "By model", "By agent"
22		lines []breakdownLine
23		total int64 // == Usage.Total().Total()
24	}
25	
26	// breakdown is the panel's content, independent of how it is drawn.
27	type breakdown struct{ blocks []breakdownBlock }
28	
29	// buildBreakdown builds the three blocks of u. rows are agentRows' output in
30	// canonical order, whatever the table's sort and filter: the agent block
31	// reuses their share so it always equals the Share column.
32	func buildBreakdown(u agentusage.Usage, rows []agentRow) breakdown {
33		total := u.Total().Total()
34		return breakdown{blocks: []breakdownBlock{
35			categoryBlock(u, total),
36			modelBlock(u, total),
37			agentBlock(rows, total),
38		}}
39	}
40	
41	// categoryBlock lists the five token categories, always, even at zero. Both
42	// cache-write lines take the cache-write role.
43	func categoryBlock(u agentusage.Usage, total int64) breakdownBlock {
44		c := u.Categories()
45		lines := []breakdownLine{
46			{label: "Input", role: theme.TokenRoleInput, tokens: c.Input},
47			{label: "Output", role: theme.TokenRoleOutput, tokens: c.Output},
48			{label: "Cache write 5 min", role: theme.TokenRoleCacheWrite, tokens: c.CacheWrite5m},
49			{label: "Cache write 1 h", role: theme.TokenRoleCacheWrite, tokens: c.CacheWrite1h},
50			{label: "Cache read", role: theme.TokenRoleCacheRead, tokens: c.CacheRead},
51		}
52		return newBlock("By category", lines, total)
53	}
54	
55	// modelBlock lists the models in ModelTotals' order (the unnamed bucket last,
56	// shown as "unknown").
57	func modelBlock(u agentusage.Usage, total int64) breakdownBlock {
58		var lines []breakdownLine
59		for _, m := range u.ModelTotals() {
60			label := m.Model
61			if label == "" {
62				label = unknownModel
63			}
64			lines = append(lines, breakdownLine{label: label, tokens: m.Tokens.Total()})
65		}
66		return newBlock("By model", lines, total)
67	}
68	
69	// agentBlock lists the agents; shares come from the rows so they match the
70	// Share column exactly.
71	func agentBlock(rows []agentRow, total int64) breakdownBlock {
72		lines := make([]breakdownLine, len(rows))
73		for i, r := range rows {
74			lines[i] = breakdownLine{label: agentLabel(r), tokens: r.Tokens.Total(), tenths: r.share}
75		}
76		return breakdownBlock{title: "By agent", lines: lines, total: total}
77	}
78	
79	// agentLabel is "orchestrator", or "<type> <short ID>" with no tree branch.
80	func agentLabel(r agentRow) string {
81		if r.Main {
82			return orchestratorLabel
83		}
84		typ := r.Type
85		if typ == "" {
86			typ = unknownType
87		}
88		return typ + " " + idCell(r)
89	}
90	
91	// newBlock fills in the shares of lines; the rounding residue goes to the
92	// largest line.
93	func newBlock(title string, lines []breakdownLine, total int64) breakdownBlock {
94		tokens := make([]int64, len(lines))
95		for i, l := range lines {
96			tokens[i] = l.tokens
97		}
98		for i, t := range shares(tokens, total, largestIndex(tokens)) {
99			lines[i].tenths = t
100		}
101		return breakdownBlock{title: title, lines: lines, total: total}
102	}
103	
104	// largestIndex is the index of the largest value, the first on a tie; -1 when empty.
105	func largestIndex(values []int64) int {
106		best := -1
107		for i, v := range values {
108			if best < 0 || v > values[best] {
109				best = i
110			}
111		}
112		return best
113	}
