15		breakdownGap      = 2 // blank cells before each numeric column
16		breakdownShareW   = 6 // "100.0%"
17		breakdownMinToken = REDACTED // "Tokens"
18		breakdownMinLabel = 8 // below this, a numeric column is dropped
19		swatchWidth       = 2 // glyph + space
20	)
21	
22	// segment is a run of plain text and the style applied once it is measured
23	// (Rule 122).
24	type segment struct {
25		text  string
26		style lipgloss.Style
27	}
28	
29	// columns is which numeric columns fit and how wide Tokens is.
30	type columns struct {
31		share, tokens bool
32		tokenW        int
33	}
34	
35	// renderBreakdown renders the panel as lines exactly width cells wide. Text is
36	// measured as plain and styled afterwards (Rule 122). A block is a header
37	// line, its lines and a Total line; blocks are separated by a blank line. A
38	// session with no token shows "-" for every share, Total included.
39	func renderBreakdown(b breakdown, width int) []string {
40		cols := fitColumns(b, width)
41		var out []string
42		for i, blk := range b.blocks {
43			if i > 0 {
44				out = append(out, theme.EmptyLineBg(width))
45			}
46			out = append(out, renderBlock(blk, cols, width)...)
47		}
48		return out
49	}
50	
51	// fitColumns drops Tokens, then Share, until every block keeps at least
52	// breakdownMinLabel cells for its label. The widest case (a category line,
53	// which carries a swatch) decides, so all blocks show the same columns.
54	func fitColumns(b breakdown, width int) columns {
55		c := columns{share: true, tokens: true, tokenW: tokenWidth(b)}
56		if labelWidth(width, swatchWidth, c) < breakdownMinLabel {
57			c.tokens = false
58		}
59		if labelWidth(width, swatchWidth, c) < breakdownMinLabel {
60			c.share = false
61		}
62		return c
63	}
64	
65	// tokenWidth is the Tokens column width: the longest figure of any block.
66	func tokenWidth(b breakdown) int {
67		w := breakdownMinToken
68		for _, blk := range b.blocks {
69			w = max(w, len(formatTokens(blk.total)))
70			for _, l := range blk.lines {
71				w = max(w, len(formatTokens(l.tokens)))
72			}
73		}
74		return w
75	}
76	
77	// labelWidth is what is left for the label after the margin, the swatch and
78	// the numeric columns.
79	func labelWidth(width, swatch int, c columns) int {
80		w := width - breakdownMargin - swatch
81		if c.share {
82			w -= breakdownGap + breakdownShareW
83		}
84		if c.tokens {
85			w -= breakdownGap + c.tokenW
86		}
87		return max(w, 0)
88	}
89	
90	// renderBlock is the header, the lines and the Total line of one block.
91	func renderBlock(blk breakdownBlock, c columns, width int) []string {
92		hasSwatch := len(blk.lines) > 0 && blk.lines[0].role != ""
93		swatch := 0
94		if hasSwatch {
95			swatch = swatchWidth
96		}
97		lw := labelWidth(width, swatch, c)
98		head := theme.HeaderStyle.Bold(true).Foreground(theme.ColorSecondary)
99	
100		out := []string{renderSegments(headerSegments(blk.title, head, hasSwatch, lw, c), width)}
101		for _, l := range blk.lines {
102			out = append(out, renderSegments(lineSegments(l, lw, c), width))
103		}
104		total := breakdownLine{label: "Total", tokens: blk.total, tenths: 1000}
105		if blk.total == 0 {
106			total.tenths = noShare
107		}
108		total.role = ""
109		if hasSwatch {
110			out = append(out, renderSegments(append([]segment{{text: strings.Repeat(" ", swatchWidth)}}, lineSegments(total, lw, c)...), width))
111		} else {
112			out = append(out, renderSegments(lineSegments(total, lw, c), width))
113		}
114		return out
115	}
116	
117	// headerSegments is the block title with the Share and Tokens column titles.
118	func headerSegments(title string, st lipgloss.Style, swatch bool, lw int, c columns) []segment {
119		segs := []segment{{text: strings.Repeat(" ", breakdownMargin)}}
120		if swatch {
121			segs = append(segs, segment{text: strings.Repeat(" ", swatchWidth)})
122		}
123		segs = append(segs, segment{text: fit(title, lw), style: st})
124		if c.share {
125			segs = append(segs, segment{text: strings.Repeat(" ", breakdownGap)},
126				segment{text: fmt.Sprintf("%*s", breakdownShareW, "Share"), style: st})
127		}
128		if c.tokens {
129			segs = append(segs, segment{text: strings.Repeat(" ", breakdownGap)},
130				segment{text: fmt.Sprintf("%*s", c.tokenW, "Tokens"), style: st})
131		}
132		return segs
133	}
134	
135	// lineSegments is one entry: margin, swatch (category only), label, columns.
136	func lineSegments(l breakdownLine, lw int, c columns) []segment {
137		segs := []segment{{text: strings.Repeat(" ", breakdownMargin)}}
138		if l.role != "" {
139			segs = append(segs, segment{text: theme.GaugeFill(1), style: theme.TokenStyle(l.role)},
140				segment{text: " "})
141		}
142		segs = append(segs, segment{text: fit(l.label, lw)})
143		if c.share {
144			share := formatShare(l.tenths)
145			segs = append(segs, segment{text: strings.Repeat(" ", breakdownGap)},
146				segment{text: fmt.Sprintf("%*s", breakdownShareW, share), style: dimIf(l.tenths <= 0)})
147		}
148		if c.tokens {
149			segs = append(segs, segment{text: strings.Repeat(" ", breakdownGap)},
150				segment{text: fmt.Sprintf("%*s", c.tokenW, formatTokens(l.tokens)), style: dimIf(l.tokens == 0)})
151		}
152		return segs
153	}
154	
155	// dimIf is DimStyle for zeros and placeholders, the plain style otherwise.
156	func dimIf(dim bool) lipgloss.Style {
157		if dim {
158			return theme.DimStyle
159		}
160		return lipgloss.NewStyle()
161	}
162	
163	// fit truncates s to w cells with an ellipsis, then pads it to exactly w.
164	func fit(s string, w int) string {
165		s = ansi.Truncate(s, w, "…")
166		return s + strings.Repeat(" ", max(w-ansi.StringWidth(s), 0))
167	}
168	
169	// renderSegments styles each measured run on the app background and pads the
170	// line to exactly width cells, cutting it if the runs overflow.
171	func renderSegments(segs []segment, width int) string {
172		var sb strings.Builder
173		used := 0
174		for _, s := range segs {
175			text := ansi.Truncate(s.text, max(width-used, 0), "")
176			if text == "" {
177				continue
178			}
179			used += ansi.StringWidth(text)
180			sb.WriteString(s.style.Background(theme.ColorBackground).Render(text))
181		}
182		return theme.PadWithBg(sb.String(), width)
183	}
184	
185	// clampTop keeps a scroll offset within [0, max(0, lines-height)].
186	func clampTop(top, lines, height int) int {
187		return min(max(top, 0), max(lines-height, 0))
188	}
