// Package agentusage reads coding-agent usage logs. It is pure stdlib and
// has no dependency on the UI.
package agentusage

import "math"

// Tokens counts the tokens of one or more agent requests.
type Tokens struct {
	Input      int64
	Output     int64
	CacheRead  int64
	CacheWrite int64
}

// Total returns the sum of the four counters, saturating at math.MaxInt64.
func (t Tokens) Total() int64 {
	return satAdd(satAdd(t.Input, t.Output), satAdd(t.CacheRead, t.CacheWrite))
}

// Add returns the field-wise sum of t and o, each field saturating at
// math.MaxInt64.
func (t Tokens) Add(o Tokens) Tokens {
	return Tokens{
		Input:      satAdd(t.Input, o.Input),
		Output:     satAdd(t.Output, o.Output),
		CacheRead:  satAdd(t.CacheRead, o.CacheRead),
		CacheWrite: satAdd(t.CacheWrite, o.CacheWrite),
	}
}

// satAdd adds two non-negative counters without wrapping.
func satAdd(a, b int64) int64 {
	if a > math.MaxInt64-b {
		return math.MaxInt64
	}
	return a + b
}
	// Known is false while the session runs (no cost-state yet), when any line
	// follows the last cost-state (the session was resumed), or when that line
	// is invalid or names another session.
	Known bool
}

// Total returns the tokens of every agent.
func (u Usage) Total() Tokens {
	var t Tokens
	for _, a := range u.Agents {
		t = t.Add(a.Tokens)
	}
	return t
}
package agentusageview

import (
	"fmt"
	"math/bits"
)

const (
	// shareScale is a share's precision: tenths of a percent.
	shareScale = 1000
	// noShare marks a share that cannot be computed: the session has no tokens.
	noShare = -1
)

// shares returns each total's part of the session total in tenths of a
// percent, floored. The entry at mainIdx takes the rounding residue so the
// parts add up to shareScale; mainIdx < 0 leaves every part floored. A zero
// total yields noShare everywhere.
func shares(totals []int64, total int64, mainIdx int) []int {
	out := make([]int, len(totals))
	if total <= 0 {
		for i := range out {
			out[i] = noShare
		}
		return out
	}
	rest := shareScale
	for i, t := range totals {
		out[i] = floorTenths(t, total)
		if i != mainIdx {
			rest -= out[i]
		}
	}
	if mainIdx >= 0 && mainIdx < len(out) {
		out[mainIdx] = max(rest, 0) // clamped: saturated totals can overshoot
	}
	return out
}

// floorTenths is floor(part*shareScale/total) on 128 bits, so no product
// overflows. part is clamped to [0, total]; total > 0.
func floorTenths(part, total int64) int {
	part = min(max(part, 0), total)
	hi, lo := bits.Mul64(uint64(part), shareScale)
	q, _ := bits.Div64(hi, lo, uint64(total)) // hi < total because part <= total
	return int(q)
}

// formatShare renders tenths of a percent: 123 is "12.3%"; noShare is "-".
func formatShare(tenths int) string {
	if tenths < 0 {
		return noValue
	}
	return fmt.Sprintf("%d.%d%%", tenths/10, tenths%10)
}
	return lipgloss.NewStyle()
}

// agentSearch is what `/` matches in the Agent column: the role. The full ID is
// searched through the ID column.
func agentSearch(r agentRow) string { return roleCell(r) }

// idCell is the ID column: the short ID of a sub-agent, a dash for the
// orchestrator, which has none.
func idCell(r agentRow) string {
	switch {
	case r.Main:
		return noValue
	case r.shortID == "":
		return unknownID
	}
	return r.shortID
}

// shareCell is the Share column.
func shareCell(r agentRow) string { return formatShare(r.share) }

// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
// its branch.
func roleCell(r agentRow) string {
	if r.Main {
		return orchestratorLabel
	}
	typ := r.Type
	if typ == "" {
		typ = unknownType
	}
	return r.branch + typ
}

// modelsCell lists the models the agent used.
func modelsCell(r agentRow) string {
	if len(r.Models) == 0 {
		return noModel
	}
	return strings.Join(r.Models, ", ")
}

// outCell is the output count. A sub-agent still being written is a floor and
// says so; the orchestrator never does, its transcript is the one being read.
func outCell(r agentRow) string {
	out := formatTokens(r.Tokens.Output)
	if !r.Main && r.PartialOutput() {
		return partialMark + out
	}
	return out
}

// formatTokens renders a count compactly, floored to one decimal: 1099 is
// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
func formatTokens(n int64) string {
	units := []struct {
		size   int64
		suffix string
	}{
		{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
	}
	for _, u := range units {
		if n < u.size {
			continue
		}
		tenths := n / (u.size / 10) // divide first: n*10 would overflow
		if tenths >= 1000 {
			return fmt.Sprintf("%d%s", tenths/10, u.suffix)
		}
		return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)

